    (function ($) {
        "use strict";
        var load = function (el, url) {
            if (url) {
                el.load(url);
            }
        }, init = function () {
            $("[data-ajax-url]").each(function () {
                var el = $(this);

                load(el, el.data("ajax-url"));
            });
        };
        init();
        $("body").on("mais.load", function () {
            init();
        });
    }(jQuery));

